CREATE POLICY "communication_source" ON "author_works" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.communication_rpc',true)='true' AND "author_works"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "author_works"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid);--> statement-breakpoint
CREATE POLICY "communication_source" ON "certificates" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.communication_rpc',true)='true' AND "certificates"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "certificates"."event_id"=nullif(current_setting('sep.event_id',true),'')::uuid);--> statement-breakpoint
CREATE POLICY "mail_worker" ON "communication_contacts" AS PERMISSIVE FOR ALL TO "sep_migrator" USING (current_setting('sep.mail_worker',true)='true') WITH CHECK (current_setting('sep.mail_worker',true)='true');--> statement-breakpoint
CREATE POLICY "mail_worker" ON "event_notifications" AS PERMISSIVE FOR ALL TO "sep_migrator" USING (current_setting('sep.mail_worker',true)='true') WITH CHECK (current_setting('sep.mail_worker',true)='true');--> statement-breakpoint
CREATE POLICY "communication_source" ON "events" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING ((current_setting('sep.communication_rpc',true)='true' AND "events"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "events"."id"=nullif(current_setting('sep.event_id',true),'')::uuid) OR current_setting('sep.mail_worker',true)='true');--> statement-breakpoint
CREATE POLICY "mail_worker" ON "mail_attempts" AS PERMISSIVE FOR ALL TO "sep_migrator" USING (current_setting('sep.mail_worker',true)='true') WITH CHECK (current_setting('sep.mail_worker',true)='true');--> statement-breakpoint
